CREATE TABLE ETL_PROCESS.T_CACHE_LOT_PART_CONTAINER_1 (
	LOT_PART_PRODUCT_INSTANCE_GROUP_SID NUMBER(38,0) NOT NULL COMMENT 'THE UNIQUE IDENTIFIER (SURROGATE KEY) FOR THE LOT.',
	CONTAINER_RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'THE UNIQUE IDENTIFIER (SURROGATE KEY) FOR THE CONTAINER.',
	VALID_FROM TIMESTAMP_LTZ(9) NOT NULL COMMENT 'THE POINT IN TIME WHEN THIS RECORD BECAME VALID.',
	VALID_TO TIMESTAMP_LTZ(9) COMMENT 'THE POINT IN TIME WHEN THIS RECORD WAS NO LONGER VALID.',
	DWH_VALID_FG BOOLEAN COMMENT 'AN INDICATOR SHOWING THE CURRENT RECORD, I.E. WHERE THE CURRENT DATE IS BETWEEN DWH_VALID_FROM AND DWH_VALID_TO.',
	SHIP_PROD_QTY NUMBER(38,5) NOT NULL COMMENT 'SHIPPED PRODUCT QUANTITY',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'THE POINT IN TIME WHEN THIS RECORD WAS CREATED IN THE DATA WAREHOUSE.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'THE POINT IN TIME WHEN THIS RECORD WAS CREATED OR LAST UPDATED.',
	DWH_SRC_FILE_NAME VARCHAR(500) COMMENT 'THE PATH AND THE NAME OF THE FILE(S) FROM WHICH THIS RECORD WAS LOADED.',
	DWH_SRC_1_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'THE POINT IN TIME WHEN THIS RECORD WAS EXTRACTED FROM THE SOURCE.',
	CONSTRAINT PK_T_CACHE_LOT_PART_CONTAINER PRIMARY KEY (LOT_PART_PRODUCT_INSTANCE_GROUP_SID, CONTAINER_RESOURCE_ITEM_SID, VALID_FROM)
)COMMENT='A SHIPMENT OF PARTICULAR PRODUCT VARIANT IN A CONTAINER';